import{_ as a,a0 as i,w as l,s as d,I as t,x as n,a1 as o,A as s,ao as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse(`{"title":"Linux有问必答：如何修复“X11 forwarding request failed on channel 0”错误 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答：如何修复“X11 forwarding request failed on channel 0”错误 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答：如何修复“X11 forwarding request failed on channel 0”错误 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答：如何修复“X11 forwarding request failed on channel 0”错误 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140818 Linux FAQs with Answers--How to fix  'X11 forwarding request failed on channel 0'","title":"Linux有问必答：如何修复“X11 forwarding request failed on channel 0”错误","tag":"201410","desc":""},"relativePath":"201410/20140818 Linux FAQs with Answers--How to fix  'X11 forwarding request failed on channel 0'.md","filePath":"[post].md"}`),f={name:"201410/20140818 Linux FAQs with Answers--How to fix  'X11 forwarding request failed on channel 0'.md"};function p(x,e,h,m,w,g){const r=i("Link");return l(),d("div",null,[e[14]||(e[14]=t("h1",{id:"linux有问必答-如何修复-x11-forwarding-request-failed-on-channel-0-错误",tabindex:"-1"},[n("Linux有问必答：如何修复“X11 forwarding request failed on channel 0”错误 "),t("a",{class:"header-anchor",href:"#linux有问必答-如何修复-x11-forwarding-request-failed-on-channel-0-错误","aria-label":"Permalink to “Linux有问必答：如何修复“X11 forwarding request failed on channel 0”错误”"},"​")],-1)),e[15]||(e[15]=t("blockquote",null,[t("p",null,[t("strong",null,"问题"),n(': 当我尝试使用SSH的X11转发选项连接到远程主机时, 我在登录时遇到了一个 "X11 forwarding request failed on channel 0" （X11 转发请求在通道0上失败）的错误。 我为什么会遇到这个错误，并且该如何修复它')])],-1)),e[16]||(e[16]=t("p",null,[t("img",{src:"https://farm6.staticflickr.com/5562/14909594691_ce7ca01b2d_z.jpg",alt:""})],-1)),t("p",null,[e[1]||(e[1]=n("首先，我们假设你已经正确启用了",-1)),o(r,{href:"http://xmodulo.com/2012/11/how-to-enable-x11-forwarding-using-ssh.html"},{default:s(()=>[...e[0]||(e[0]=[n("SSH的X11转发",-1)])]),_:1}),e[2]||(e[2]=n("。",-1))]),e[17]||(e[17]=u(`<p>如果你在登录时遇到&quot;X11 forwarding request failed on channel 0&quot; （X11 转发请求在通道0上失败），这里可能有不同的原因，解决的方法也不同。</p><h3 id="方案一" tabindex="-1">方案一 <a class="header-anchor" href="#方案一" aria-label="Permalink to “方案一”">​</a></h3><p>出于安全原因，OpenSSH服务默认将X11转发请求绑定到本地回环地址上，并且在DISPLAY环境变量中将主机名设置为“localhost”。在这样的设定下，一些 X11客户端不能正确处理X11转发，这会导致报告中的错误。要解决这个问题，在/etc/ssh/sshd配置文件中加入下面这几行，它可以将X11转发请求绑定到外网卡地址上。</p><pre><code>$ sudo vi /etc/ssh/sshd_config 
</code></pre><hr><pre><code>X11Forwarding yes
X11UseLocalhost no
</code></pre><p>重启SSH使设置生效:</p><pre><code>$ sudo /etc/init.d/ssh restart (Debian 6, Ubuntu or Linux Mint)
$ sudo systemctl restart ssh.service (Debian 7, CentOS/RHEL 7, Fedora)
$ sudo service sshd restart (CentOS/RHEL 6) 
</code></pre><h3 id="方案二" tabindex="-1">方案二 <a class="header-anchor" href="#方案二" aria-label="Permalink to “方案二”">​</a></h3><p>如果远程主机的SSH服务禁止了IPv6，那么X11转发失败的错误也有可能发生。要解决这个情况下的错误。打开/etc/ssh/sshd配置文件，取消对&quot;AddressFamily all&quot; （如果有这条的话）的注释。接着加入下面这行。这会强制SSH服务只使用IPv4而不是IPv6。（LCTT 译注：此处恐有误，AddressFamily 没有 all 这个参数，而 any 代表同时支持 IPv6和 IPv4，以此处的场景而言，应该是关闭IPv6支持，只支持 IPv4，所以此处应该是“注释掉 AddressFamily any”才对。）</p><pre><code>$ sudo vi /etc/ssh/sshd_config 
</code></pre><hr><pre><code>AddressFamily inet
</code></pre><p>再说一次，重启SSH服务来完成设置</p><hr>`,15)),t("p",null,[e[4]||(e[4]=n("via: ",-1)),o(r,{href:"http://ask.xmodulo.com/fix-broken-x11-forwarding-ssh.html"},{default:s(()=>[...e[3]||(e[3]=[n("http://ask.xmodulo.com/fix-broken-x11-forwarding-ssh.html",-1)])]),_:1})]),t("p",null,[e[7]||(e[7]=n("译者：",-1)),o(r,{href:"https://github.com/geekpi"},{default:s(()=>[...e[5]||(e[5]=[n("geekpi",-1)])]),_:1}),e[8]||(e[8]=n(" 校对：",-1)),o(r,{href:"https://github.com/wxy"},{default:s(()=>[...e[6]||(e[6]=[n("wxy",-1)])]),_:1})]),t("p",null,[e[11]||(e[11]=n("本文由 ",-1)),o(r,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[9]||(e[9]=[n("LCTT",-1)])]),_:1}),e[12]||(e[12]=n(" 原创翻译，",-1)),o(r,{href:"http://linux.cn/"},{default:s(()=>[...e[10]||(e[10]=[n("Linux中国",-1)])]),_:1}),e[13]||(e[13]=n(" 荣誉推出",-1))])])}const S=a(f,[["render",p]]);export{T as __pageData,S as default};
